    16	const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    17	
    18	function validateEmail(email: string): void {
    19	  if (!email || email.trim().length === 0) {
    20	    throw new ValidationError('Email is required and must not be empty');
    21	  }
    22	  if (!EMAIL_REGEX.test(email)) {
    23	    throw new ValidationError('Invalid email format');
