    42	  async create(data: CreateEmployeeDto): Promise<Employee> {
    43	    if (!data.fullName || data.fullName.trim().length === 0) {
    44	      throw new ValidationError('fullName is required and must not be empty');
    45	    }
    46	    const email = data.email.trim();
    47	    validateEmail(email);
    48	
