    58	  async update(id: string, data: UpdateEmployeeDto): Promise<Employee | null> {
    59	    const existing = await this.repository.findById(id);
    60	    if (!existing) {
    61	      return null;
    62	    }
    63	
    64	    if (data.email !== undefined) {
    65	      const email = data.email.trim();
    66	      validateEmail(email);
    67	      data = { ...data, email };
    68	    }
    69	
    70	    const updateData: Partial<Employee> = { ...data, updatedAt: new Date() };
    71	    return this.repository.update(id, updateData);
    72	  }
